package TestYAMLBase;

sub new {
    my $self = bless {}, shift;
    while (my ($k, $v) = splice @_, 0, 2) {
        $self->{$k} = $v;
    }
    return $self;
}

1;

package TestYAML;
use lib 'inc';
use Test::YAML -Base;

$Test::YAML::YAML = 'YAML';

$^W = 1;

use strict;
use lib -e 't' ? 't' : 'test';
use TestYAML tests => 1;

pass('TestYAML framework loads');

use Test::More;
use YAML;

YAML::Load("a: b");
YAML::Load("a:\n  b: c");
YAML::Load("a: b\nc: d");

pass "YAML w/o final newlines loads";

done_testing;

use strict;
use warnings;

use Test::More tests => 1;

my $success = 0;
my $err;
{
    local $@;
    eval {
        require YAML::Dumper;
        my $hash   = {};
        my $dumper = YAML::Dumper->new();
        my $string = $dumper->dump($hash);
        $success = 1;
    };
    $err = $@;
}
is( $success, 1, "Basic YAML::Dumper usage worked as expected" )
  or diag( explain($err) );

use strict;
use lib -e 't' ? 't' : 'test';
use TestYAML;

run_is;

sub yaml_dump {
    return Dump(@_);
}

